<script>
 import {tasks} from '../stores/tasks.svelte';
 import {ratios,ratioLabel} from '../lib/ratio.ts';import {editor} from '../stores/editor.svelte';import {chooseRatioCommand,swapRatioCommand} from '../services/commands.js';import {ArrowLeftRight} from 'lucide-svelte';
 let {disabled=false,onerror=()=>{},onapply=()=>{}}=$props();let pending=$state(false),taskId=$state(null);const busy=$derived(pending||taskId&&['queued','running','waiting'].includes(tasks.byId[taskId]?.state));async function apply(ratio){pending=true;try{const result=ratio===null?await swapRatioCommand():await chooseRatioCommand(ratio);taskId=result?.task?.id||null;onapply(result);}catch(error){onerror(error);}finally{pending=false;}}
</script>
<div class="ratio-bar" role="group" aria-label="图片比例">{#each ratios as ratio,i}<button type="button" disabled={disabled||busy} class:active={editor.ratio.ratio===ratio} aria-pressed={editor.ratio.ratio===ratio} title={`比例 ${ratio} · ${i+1}`} onclick={()=>apply(ratio)}>{editor.ratio.ratio===ratio?ratioLabel(editor.ratio):ratio}</button>{/each}<button type="button" disabled={disabled||busy||editor.ratio.ratio==='1:1'} title="交换横竖 · R" aria-label="交换横竖" onclick={()=>apply(null)}><ArrowLeftRight size={15}/></button></div>
<style>.ratio-bar{display:inline-flex;flex-wrap:wrap;gap:2px;padding:2px;border:1px solid var(--border);border-radius:6px;background:var(--bg-sunken)}.ratio-bar button{display:inline-flex;align-items:center;justify-content:center;min-width:36px;min-height:28px;padding:4px 6px;border:1px solid transparent;border-radius:4px;background:transparent;color:var(--text-dim);font:12px system-ui,sans-serif;cursor:pointer}.ratio-bar button.active{background:var(--bg-elev);border-color:var(--border);color:var(--text)}.ratio-bar button:hover{background:var(--accent-soft)}.ratio-bar button:active{border-color:var(--accent)}.ratio-bar button:focus-visible{outline:2px solid var(--focus);outline-offset:2px}.ratio-bar button:disabled{opacity:.45;cursor:default}</style>
